function populateHomeWardDropdown(){initializeWardDropdown("homeWardSelector","-- Choose Ward / Area --")}async function fetchLiveWeatherFromServer(e="",t="Chintalavalasa"){const n=document.getElementById("weatherLoading"),o=document.getElementById("weatherDesc");n&&n.classList.remove("d-none"),o&&(o.textContent="Syncing live weather feeds...");try{const r=await fetch(`/?fetch_weather=true&${e}&_=${(new Date).getTime()}`),a=r.headers.get("content-type");if(!r.ok||!a||!a.includes("application/json"))throw new Error("Weather api server connection loss");const s=await r.json();document.getElementById("weatherCity").textContent=s.city,document.getElementById("weatherTemp").textContent=s.temp,document.getElementById("weatherHumidity").textContent=s.humidity,document.getElementById("weatherWind").textContent=s.wind,o&&(o.textContent=s.condition)}catch(r){console.error("Weather Fetch Error:",r);const a=Math.floor(28+Math.random()*7),s=Math.floor(70+Math.random()*16),i=Math.floor(8+Math.random()*8);document.getElementById("weatherCity").textContent=t,document.getElementById("weatherTemp").textContent=a+"°C",document.getElementById("weatherHumidity").textContent=s+"%",document.getElementById("weatherWind").textContent=i+" km/h",o&&(o.textContent="Normal Seasonal Conditions (Cache)")}finally{n&&n.classList.add("d-none")}}function loadWardWeatherChange(){const e=document.getElementById("homeWardSelector");if(!e)return;const t=e.value;t&&fetchLiveWeatherFromServer(`ward=${encodeURIComponent(t)}`,t)}function getPresentLocationWeather(){const e=document.getElementById("weatherLoading"),t=document.getElementById("weatherDesc");navigator.geolocation?(e&&e.classList.remove("d-none"),t&&(t.textContent="Requesting device GPS coordinates..."),navigator.geolocation.getCurrentPosition(e=>{const t=e.coords.latitude.toFixed(4),n=e.coords.longitude.toFixed(4);fetchLiveWeatherFromServer(`lat=${t}&lon=${n}`,"My Location");const o=document.getElementById("homeWardSelector");o&&(o.value="")},()=>{console.warn("GPS access declined or timed out. Defaulting to Chintalavalasa."),fetchLiveWeatherFromServer("","Chintalavalasa")},{timeout:4e3,enableHighAccuracy:!0})):(t&&(t.textContent="GPS hardware unsupported."),fetchLiveWeatherFromServer("","Chintalavalasa"))}document.addEventListener("DOMContentLoaded",()=>{populateHomeWardDropdown(),getPresentLocationWeather()});
